import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;

    static int addModulo(int x, int y) {
        x += y;
        if (x >= MOD) x -= MOD;
        return x;
    }

    static int multiplyModulo(int x, int y) {
        long res = 1L * x * y;
        if (res >= MOD) res %= MOD;
        return (int) res;
    }

    static int subtractModulo(int x, int y) {
        x -= y;
        if (x < 0) x += MOD;
        return x;
    }

    static int powModulo(int base, int exp) {
        int res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = multiplyModulo(res, base);
            base = multiplyModulo(base, base);
            exp >>= 1;
        }
        return res;
    }

    static int getLowbitValue(int x) {
        return x & (-x);
    }

    static int n;
    static int[][] a = new int[10][10];
    static int[][] qarr = new int[10][1 << 10];
    static int[][] dparr = new int[11][1 << 10];
    static Map<BigInteger, Integer> id_map = new HashMap<>();
    static int cnt = 0;
    static int[][] ch; // Will initialize later based on cnt
    static int[][][] chArray; // 2D array for ch, size to be determined dynamically

    // Since Java doesn't have Bitset with custom size, we'll represent it as BigInteger
    static Map<BigInteger, Integer> bitsetMap = new HashMap<>();
    static List<BigInteger> bitsetList = new ArrayList<>();

    static int dfsBitset(BigInteger s) {
        if (id_map.containsKey(s))
            return id_map.get(s);
        id_map.put(s, ++cnt);
        int currentId = cnt;
        int maxMask = 1 << n;
        for (int i = 0; i < maxMask; i++) {
            BigInteger tmp = s;
            for (int j = 0; j < maxMask; j++) {
                if (!getBit(tmp, j)) {
                    int x = i & j;
                    while (x != 0) {
                        int t = getLowbitValue(x);
                        if (getBit(s, j ^ t)) {
                            tmp = setBit(tmp, j);
                            break;
                        }
                        x -= t;
                    }
                }
            }
            ch[currentId][i] = dfsBitset(tmp);
        }
        return currentId;
    }

    static boolean getBit(BigInteger bits, int position) {
        return bits.testBit(position);
    }

    static BigInteger setBit(BigInteger bits, int position) {
        return bits.setBit(position);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        n = sc.nextInt();

        // Initialize ch array after we know cnt (which is calculated after dfs)
        // But in Java, it's better to initialize large enough memory beforehand.
        // Max number of nodes can be up to (size depending),
        // but since our code doesn't provide the bound, we assume a safe large number.
        int MAX_NODES = 70010;
        ch = new int[MAX_NODES][1 << 10];

        // Starting bitset with only the first bit set
        BigInteger startBitset = BigInteger.ONE.setBit(0);

        // Run dfs to build maps
        dfsBitset(startBitset);

        // Read matrix a
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                a[i][j] = sc.nextInt();
                a[i][j] = multiplyModulo(a[i][j], powModulo(100, MOD - 2));
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < (1 << n); j++) {
                qarr[i][j] = 1;
                for (int k = 0; k < n; k++) {
                    if (((j >> k) & 1) == 1) {
                        qarr[i][j] = multiplyModulo(qarr[i][j], a[i][k]);
                    } else {
                        qarr[i][j] = multiplyModulo(qarr[i][j], subtractModulo(1, a[i][k]));
                    }
                }
            }
        }

        // Initialize dparr
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dparr[i], 0);
        }
        dparr[0][1] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= cnt; j++) {
                for (int k = 0; k < (1 << n); k++) {
                    int chVal = ch[j][k];
                    dparr[i][chVal] = addModulo(dparr[i][chVal], multiplyModulo(dparr[i - 1][j], qarr[i - 1][k]));
                }
            }
        }

        // Construct full bits with all bits set to 1
        BigInteger bits = BigInteger.ZERO;
        for (int i = 0; i < (1 << n); i++) {
            bits = bits.setBit(i);
        }

        Integer result = dparr[n][id_map.get(bits)];
        if (result == null)
            result = 0;
        System.out.println(result);
    }
}

